(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const s = window.__toolboxStore;
  const out = {};
  out.libraryBefore = (await s.listLibrary()).length;

  // ① 把识别设置切到「本机配置」，指向本地模拟服务（不花真实额度）
  await s.setSetting('ai_config', JSON.stringify({
    mode: 'local-key', baseUrl: 'http://127.0.0.1:8799/v1', apiKey: 'mock-key', model: 'mock-vision',
  }));

  // ② 打开一个作品，进识别弹层
  const cards = [...document.querySelectorAll('.tb-project-main')];
  const card = cards.find((c) => (c.innerText || '').includes('循迹小车')) || cards[0];
  out.work = (card?.innerText || '').split('\n')[0];
  card?.click();
  await sleep(3200);
  const projects = await s.listProjects();
  const project = projects.find((p) => p.name === out.work) || projects[0];
  out.rowsBefore = (await s.getProject(project.id))?.components.length ?? null;

  [...document.querySelectorAll('.pj-head-actions button')].find((b) => b.textContent.includes('AI 识别元件'))?.click();
  await sleep(1600);
  out.modalOpen = !!document.querySelector('.lr-modal');
  const fileInput = document.querySelector('.lr-card input[type=file]');
  out.hasFileInput = !!fileInput;
  if (!fileInput) { out.hint = document.querySelector('.lr-card h3')?.textContent || null; return JSON.stringify(out); }

  // ③ 造一张测试照片喂进去（模拟服务不看图）
  const c = document.createElement('canvas'); c.width = 96; c.height = 96;
  const g = c.getContext('2d'); g.fillStyle = '#111'; g.fillRect(0, 0, 96, 96);
  g.fillStyle = '#0f0'; g.fillRect(20, 20, 56, 56);
  const blob = await new Promise((r) => c.toBlob(r, 'image/png'));
  const dt = new DataTransfer();
  dt.items.add(new File([blob], 'photo.png', { type: 'image/png' }));
  fileInput.files = dt.files;
  fileInput.dispatchEvent(new Event('change', { bubbles: true }));
  await sleep(1000);

  // ④ 开始识别
  [...document.querySelectorAll('.lr-btn')].find((b) => b.textContent.includes('开始识别'))?.click();
  for (let i = 0; i < 30; i++) {
    await sleep(500);
    if (document.querySelector('.lr-list')) break;
  }
  out.msg = document.querySelector('.lr-msg')?.textContent || null;
  out.recognized = [...document.querySelectorAll('.lr-list .lr-name')].map((e) => e.textContent);
  out.rowsAfterRecognize = (await s.getProject(project.id))?.components.length ?? null;

  // ⑤ 存进我的元件库
  const saveBtn = [...document.querySelectorAll('.lr-btn')].find((b) => b.textContent.includes('存进我的元件库'));
  out.hasSaveButton = !!saveBtn;
  saveBtn?.click();
  await sleep(3000);
  out.msgAfterSave = document.querySelector('.lr-msg')?.textContent || null;

  const lib = await s.listLibrary();
  out.libraryAfter = lib.length;
  out.aiItems = lib.filter((x) => x.source === 'ai_temp').map((x) => ({ name: x.name, cat: x.category, img: !!x.imageUrl, purpose: x.purpose }));
  const bundle = await s.getProject(project.id);
  out.rowsWithLibrary = bundle.components.filter((x) => x.libraryId).map((x) => x.name);

  // ⑥ 收尾：切回手动模式，别把测试配置留下
  await s.setSetting('ai_config', JSON.stringify({ mode: 'manual', baseUrl: '', apiKey: '', model: '' }));
  out.restored = true;
  return JSON.stringify(out);
})()
